    async def upgrade_instance(
        self,
        *,
        instance_id: str,
        region: str | None = None,
        node_type: str | None = None,
        enable_ha: bool | None = None,
        high_availability_mode: HighAvailabilityMode | None = None,
        volume_size: int | None = None,
        volume_type: VolumeType | None = None,
        upgradable_version_id: str | None = None,
        major_upgrade_workflow: UpgradeInstanceRequestMajorUpgradeWorkflow
        | None = None,
        enable_encryption: bool | None = None,
    ) -> Instance:
        """
        Upgrade a Database Instance

        Upgrade your current Database Instance specifications like node type, high
        availability, volume, or the database engine version. Note that upon upgrade the
        `enable_ha` parameter can only be set to `true`.

        Args:
            region: The region you want to target
            instance_id: UUID of the Database Instance you want to upgrade.
            node_type: Node type of the Database Instance you want to upgrade to.
                Precisely one of node_type, enable_ha, high_availability_mode,
                volume_size, volume_type, upgradable_version_id, major_upgrade_workflow,
                enable_encryption can be set.
            enable_ha: Defines whether or not high availability should be enabled on the
                Database Instance. Precisely one of node_type, enable_ha,
                high_availability_mode, volume_size, volume_type, upgradable_version_id,
                major_upgrade_workflow, enable_encryption can be set.
            high_availability_mode: Defines the High-Availability mode of the instance.
                Precisely one of node_type, enable_ha, high_availability_mode,
                volume_size, volume_type, upgradable_version_id, major_upgrade_workflow,
                enable_encryption can be set.
            volume_size: Increase your block storage volume size. Precisely one of
                node_type, enable_ha, high_availability_mode, volume_size, volume_type,
                upgradable_version_id, major_upgrade_workflow, enable_encryption can be
                set.
            volume_type: Change your Database Instance storage type. Precisely one of
                node_type, enable_ha, high_availability_mode, volume_size, volume_type,
                upgradable_version_id, major_upgrade_workflow, enable_encryption can be
                set.
            upgradable_version_id: Update your database engine to a newer version. This
                will create a new Database Instance with same specifications as the
                current one and perform a Database Engine upgrade. (UUID format)
                Precisely one of node_type, enable_ha, high_availability_mode,
                volume_size, volume_type, upgradable_version_id, major_upgrade_workflow,
                enable_encryption can be set.
            major_upgrade_workflow: Upgrade your database engine to a new major version
                including instance endpoints. Precisely one of node_type, enable_ha,
                high_availability_mode, volume_size, volume_type, upgradable_version_id,
                major_upgrade_workflow, enable_encryption can be set.
            enable_encryption: Defines whether or not encryption should be enabled on
                the Database Instance. Precisely one of node_type, enable_ha,
                high_availability_mode, volume_size, volume_type, upgradable_version_id,
                major_upgrade_workflow, enable_encryption can be set.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/rdb/v1/regions/{region}/instances/{instance_id}/upgrade",
                region=self._client.region(region),
                instance_id=instance_id,
            ),
            body={
                "node_type": node_type,
                "enable_ha": enable_ha,
                "high_availability_mode": high_availability_mode,
                "volume_size": volume_size,
                "volume_type": volume_type,
                "upgradable_version_id": upgradable_version_id,
                "major_upgrade_workflow": major_upgrade_workflow,
                "enable_encryption": enable_encryption,
            },
        )
        return Instance.model_validate(data)

